package com.spaceagent.platform.integration.infrastructure.http;
import com.spaceagent.platform.automation.api.AutomationTriggerApplicationApi;import com.spaceagent.platform.automation.domain.AutomationTriggerSource;import com.spaceagent.shared.api.ApiResponse;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.util.*;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/automation-triggers") public class PlatformAutomationTriggerHttpController{private final AutomationTriggerApplicationApi api;public PlatformAutomationTriggerHttpController(AutomationTriggerApplicationApi api){this.api=api;}@PostMapping @ResponseStatus(HttpStatus.CREATED) public ApiResponse<?> create(@RequestHeader("Idempotency-Key") String key,@Valid @RequestBody WriteRequest r,Authentication a){PlatformHttpSupport.requireWrite(a);return ApiResponse.ok(api.create(new AutomationTriggerApplicationApi.CreateCommand(tenant(a),user(a),r.agentId(),r.description(),r.prompt(),source(r),key)));}@PostMapping("/{lineageId}/versions") @ResponseStatus(HttpStatus.CREATED) public ApiResponse<?> version(@PathVariable String lineageId,@RequestHeader("Idempotency-Key") String key,@Valid @RequestBody VersionRequest r,Authentication a){PlatformHttpSupport.requireWrite(a);var d=r.definition();return ApiResponse.ok(api.createVersion(new AutomationTriggerApplicationApi.CreateVersionCommand(tenant(a),user(a),lineageId,r.expectedCurrentVersion(),d.description(),d.prompt(),source(d),key)));}@PostMapping("/{id}/{action}") public ApiResponse<?> lifecycle(@PathVariable String id,@PathVariable String action,@RequestParam long expectedRevision,Authentication a){PlatformHttpSupport.requireWrite(a);var c=new AutomationTriggerApplicationApi.LifecycleCommand(tenant(a),user(a),id,expectedRevision);return ApiResponse.ok(switch(action){case "activate"->api.activate(c);case "pause"->api.pause(c);case "archive"->api.archive(c);default->throw new IllegalArgumentException("unsupported Trigger action");});}@GetMapping("/{id}") public ApiResponse<?> get(@PathVariable String id,Authentication a){return ApiResponse.ok(api.get(new AutomationTriggerApplicationApi.GetQuery(tenant(a),user(a),id)));}@GetMapping public ApiResponse<?> list(@RequestParam String agentId,Authentication a){return ApiResponse.ok(api.list(new AutomationTriggerApplicationApi.ListQuery(tenant(a),user(a),agentId)));}private static String tenant(Authentication a){return PlatformHttpSupport.tenantId(a);}private static String user(Authentication a){return PlatformHttpSupport.userId(a);}private static AutomationTriggerSource source(WriteRequest r){return switch(r.type()){case "WEBHOOK"->new AutomationTriggerSource.Webhook(r.signingKeyRefs(),"HMAC_SHA256",r.maxBodyBytes(),r.maxAgeSeconds());case "REPOSITORY"->new AutomationTriggerSource.Repository(r.installationId(),r.connectionId(),r.connectionRevision(),r.capabilitySnapshotId(),r.snapshotSha256(),r.providerRepositoryId(),r.events());case "TASK_COMPLETION"->new AutomationTriggerSource.TaskCompletion(r.projectId(),r.taskId(),r.outcomes());case "FOLLOW_UP"->new AutomationTriggerSource.FollowUp(r.conversationId(),r.sourceTaskId(),r.delaySeconds());default->throw new IllegalArgumentException("unsupported Trigger type");};}public record WriteRequest(@NotBlank String agentId,@NotBlank @Size(max=200) String description,@NotBlank @Size(max=32000) String prompt,@NotBlank String type,List<String> signingKeyRefs,Integer maxBodyBytes,Integer maxAgeSeconds,String installationId,String connectionId,Long connectionRevision,String capabilitySnapshotId,String snapshotSha256,String providerRepositoryId,Set<AutomationTriggerSource.RepositoryEvent> events,String projectId,String taskId,Set<AutomationTriggerSource.TaskOutcome> outcomes,String conversationId,String sourceTaskId,Integer delaySeconds){}public record VersionRequest(@Min(1) int expectedCurrentVersion,@Valid @NotNull WriteRequest definition){} }
